cat > /tmp/cls.py <<'EOF'
import json, collections, statistics as st
qs=[]
for l in open('lab_log.jsonl'):
    d=json.loads(l)
    if d['op']=='dev_sample': qs+=d['result']['questions']
for t in ['algebra','geometry','combinatorics','number_theory']:
    cls=collections.defaultdict(list)
    nshared=0; nq=0
    for q in qs:
        if q['topic']!=t: continue
        nq+=1
        cnt=collections.Counter(s['answer'] for s in q['samples'])
        vs=collections.defaultdict(set)
        for s in q['samples']: vs[s['answer']].add(s['variant'])
        for s in q['samples']:
            if s['correct']: cls['correct'].append(s['score'])
            elif cnt[s['answer']]==1: cls['wrong_single'].append(s['score'])
            else: cls['wrong_rep'].append(s['score'])
        # shared wrong attractors: wrong answers appearing in >=2 variants
        shared=[a for a in vs if len(vs[a])>=2 and a!=q['correct_answer']]
        nshared+=len(shared)>0
    print("==",t, "questions with a wrong answer in >=2 variants:",nshared,"/",nq)
    for k,v in cls.items():
        v=sorted(v)
        print(f"  {k:13s} n={len(v):3d} mean={st.mean(v):.2f} sd={st.pstdev(v):.2f} q05={v[int(.05*len(v))]:.2f} q50={v[len(v)//2]:.2f} q95={v[int(.95*len(v))]:.2f}")
EOF
python3 /tmp/cls.py
